async function api(a,d,f){let r;try{r=await fetch('api.php?a='+a,{method:'POST',headers:f?{}:{'Content-Type':'application/json'},body:f||JSON.stringify(d||{})})}catch(e){S.stale=true;const c=CACHED.includes(a)&&localStorage['c_'+a];if(c){if(!navigator.onLine)offShow();const j=JSON.parse(c);if(a=='settings')j.now=Date.now();return j}if(!navigator.onLine){offShow();throw new Error(t('offline'))}throw new Error(t('srv_err'))}S.stale=false;const j=await r.json().catch(()=>({error:'Server javobi xato'}));if(j.error)throw new Error(j.error);if(CACHED.includes(a)&&!(S.user&&S.user.role!='customer'))try{localStorage['c_'+a]=JSON.stringify(j)}catch(e){}return j}
const CACHED=['products','banners','settings'];
const toast=(m,e)=>{const x=$('#toast');x.textContent=m;x.className='on'+(e?' err':'');setTimeout(()=>x.className='',2400)};
const run=async f=>{try{await f()}catch(e){toast(e.message,1)}};
const save=()=>{localStorage.cart=JSON.stringify(S.cart);localStorage.wish=JSON.stringify(S.wish);localStorage.rv=JSON.stringify(S.rv);wcUp();syncLater()};
const cats=()=>[...new Set(S.products.map(p=>p.category))];
const P=id=>S.products.find(p=>p.id==id);
const sale=p=>p.old_price>p.price?Math.round((1-p.price/p.old_price)*100):0;
const ad=(p,sz)=>p.variants&&p.variants[sz]?p.variants[sz].add:0;
const vp=(p,sz)=>p.price+ad(p,sz),vo=(p,sz)=>sale(p)?p.old_price+ad(p,sz):0,vs=(p,sz)=>p.variants&&sz&&p.variants[sz]?p.variants[sz].stock:p.stock;
const sub=()=>S.cart.reduce((s,c)=>s+(P(c.id)?vp(P(c.id),c.size)*c.qty:0),0);
const disc=()=>{if(!S.promo)return 0;const s=sub();return Math.min(s,S.promo.type=='pct'?Math.floor(s*S.promo.val/100):S.promo.val)};
const cnt=()=>S.cart.reduce((s,c)=>s+c.qty,0);
function dlv(amt,reg=S.reg,m=S.mth){const r=(S.set.delivery[reg]||{})[m];if(!r)return{price:0,min:0,max:0,free:false};const free=m=='courier'&&amt>=S.set.free_ship;return{price:free?0:r[0],min:r[1],max:r[2],free}}
const eta=r=>r.max==0?t('d0'):r.min==0?t('d01'):r.min==r.max?t('day1',{a:r.min}):t('days',{a:r.min,b:r.max});
const stars=p=>p.rcount?`<small class="rt"><span>★</span> ${p.rating.toFixed(1)} <span class="mut">(${p.rcount})</span></small>`:'';
function cdTxt(){const e=S.set.promo_end;if(!e)return null;const ms=e-(Date.now()+S.off);if(ms<=0)return null;const s=Math.floor(ms/1e3),dd=Math.floor(s/86400),z=n=>String(n).padStart(2,'0');return(dd?dd+t('dd')+' ':'')+z(Math.floor(s%86400/3600))+':'+z(Math.floor(s%3600/60))+':'+z(s%60)}
const cdEl=()=>cdTxt()?`<span class="cdb" data-cd><i></i>${t('cd',{t:'<b>'+cdTxt()+'</b>'})}</span>`:'';
setInterval(()=>document.querySelectorAll('[data-cd]').forEach(e=>{const x=cdTxt();e.style.display=x?'':'none';const b=e.querySelector('b');if(x&&b)b.textContent=x}),1000);
/* ---------- modal ---------- */
function modal(h,wide,na){$('#md').className='';$('#md').innerHTML=`<div class="sheet ${wide?'wide':''} ${na?'na':''}" onclick="event.stopPropagation()">${h}</div>`;$('#md').onclick=closeM}
const closeM=()=>{$('#md').className='hide';$('#md').innerHTML='';if(/^#p\d+$/.test(location.hash))history.replaceState(null,'',location.pathname+location.search)};
/* ---------- umumiy maket ---------- */
function head(){const v=S.view,tb=(k,n)=>`<button class="chip ${v==k?'blue':''}" onclick="go('${k}')">${n}</button>`;
return `<div class="mock nav"><span class="logo" onclick="go('shop')">TS</span><b class="brand" onclick="go('shop')">TREND STORE</b><i class="fl"></i><button class="chip" onclick="S.view='shop';render();$('#sr').classList.toggle('hide');$('#sr').focus()">⌕</button>${tb('shop',t('shop'))}${staff()?tb('stock',t('stock')):''}${tb('orders',t('orders'))}<button class="chip ${v=='wish'?'blue':''}" id="wc" onclick="go('wish')">♡${S.wish.length?' '+S.wish.length:''}</button>${admin()?tb('promos',t('promos'))+tb('users',t('sellers'))+tb('stats','📊 '+t('stats')):''}<span class="lgs">${['uz','ru','en'].map(l=>`<button class="${l==lang?'on':''}" onclick="setLang('${l}')">${l.toUpperCase()}</button>`).join('')}</span>${thBtn()}${S.user?`<button class="chip ${v=='profile'?'blue':''}" onclick="go('profile')" title="${t('prof_t')}">👤<span class="hn"> ${E(S.user.name)}</span></button><button class="chip" onclick="logout()">${t('logout')}</button>`:`<button class="chip line" onclick="authOpen('login')">${t('login')}</button>`}</div>`}
function foot(){const c=S.set.contact||{};return `<div class="ft"><div class="cols"><div><h4>TREND STORE</h4><p>${t('f_brand')}</p><p>${t('f_sub')}</p></div><div><h4>${t('f_help')}</h4><p>${t('f_dlv')}</p><p>${t('f_pay')}</p><p>${t('f_ret')}</p></div><div><h4>${t('f_contact')}</h4><p><a href="https://t.me/${E(c.tg)}" target="_blank">${t('f_tg')}</a></p><p><a href="tel:${E(c.phone)}">${E(c.phone)}</a></p><p>${t('f_hours')}: 09:00–21:00</p></div><div><h4>${t('f_acc')}</h4><p><a onclick="authOpen('login')">${t('login')}</a></p><p><a onclick="authOpen('register')">${t('reg_btn')}</a></p><p><a onclick="go('profile')">${t('prof_t')}</a></p><p><a onclick="go('orders')">${t('my_orders')}</a></p></div></div><p class="cp">${t('copy')}</p></div><nav class="mnav"><button class="${S.view=='shop'?'on':''}" onclick="go('shop')">${t('shop')}</button><button onclick="go('shop');$('#sr').classList.remove('hide');$('#sr').focus()">⌕ ${t('m_search')}</button><button onclick="cartOpen()">${t('cart')}${cnt()?' ('+cnt()+')':''}</button><button onclick="${S.user?"go('profile')":"authOpen('login')"}">${t('m_profile')}</button></nav>`}
function bar(){const a=sub()-disc(),r=dlv(a),left=Math.max(0,S.set.free_ship-a);$('#bar').innerHTML=cnt()?`<div class="fb" onclick="cartOpen()"><div><b>${t('cart_bar',{n:cnt(),s:fmt(a)})}</b>${S.mth=='courier'?`<div class="fsb"><i style="width:${Math.min(100,a/S.set.free_ship*100)}%"></i></div>`:''}</div><span>${t('view')}</span></div>`:''}
function fab(){const c=S.set.contact||{};$('#fab').innerHTML=`<div class="fab">${S.cmp.length?`<button class="fb2 cm" onclick="cmpOpen()" title="${t('cmp')}">⇄<b>${S.cmp.length}</b></button>`:''}<a class="fb2" href="https://t.me/${E(c.tg)}" target="_blank" title="Telegram">TG</a><a class="fb2" href="tel:${E(c.phone)}" title="${t('call')}">☎</a><button class="fb2 up" id="upb" onclick="scrollTo({top:0,behavior:'smooth'})" title="${t('up')}">↑</button></div>`;upv()}
const upv=()=>{const u=$('#upb');if(u)u.classList.toggle('show',scrollY>400)};addEventListener('scroll',upv);
function render(){$('#app').innerHTML=head()+'<main>'+V[S.view]()+foot()+'</main>';if(S.view=='shop'){grid();rvRow();heroSet(CI);heroPlay()}bar();fab();setTimeout(mmUpdate,30)}
function go(v){if((v=='orders'||v=='profile')&&!S.user)return authOpen('login');S.view=v;run(async()=>{if(v=='orders'||v=='stock')S.orders=await api('orders');if(v=='users')S.users=await api('users');if(v=='stats')S.stats=await api('stats');if(v=='promos')S.banners=await api('banners');render();scrollTo(0,0)})}
/* ---------- vitrina ---------- */
const V={};
const QF=[['all','all'],['sale','sale'],['new','new'],['hit','hit']];
const chipList=()=>[...QF.map(([k,f])=>({t:t(k),f})),...cats().map(c=>({t:cn(c),c}))];
const chipOn=x=>x.c?S.cat==x.c&&S.f=='all':S.f==x.f&&S.cat=='Barchasi';
const setChip=i=>{const x=chipList()[i];S.cat=x.c||'Barchasi';S.f=x.f||'all';render()};
const resetF=()=>{S.fl={min:'',max:'',sale:false,stock:false};S.q='';S.cat='Barchasi';S.f='all';S.sort='def';render()};
V.shop=()=>hero()+`<div class="srw"><input id="sr" class="${S.q?'':'hide'}" style="margin:0 0 14px" placeholder="${t('search_ph')}" value="${E(S.q)}" autocomplete="off" oninput="S.q=this.value;grid();shShow();shLater()" onfocus="shShow()" onblur="shHide()" onkeydown="acKey(event)">${SR?`<button class="vb" id="vb" type="button" onclick="voiceS()" title="${t('voice')}">🎤</button>`:''}<div id="sh" class="shd hide"></div></div><div id="s-cat" class="chips">${chipList().map((x,i)=>`<button class="chip ${chipOn(x)?'blue':''}" onclick="setChip(${i})">${E(x.t)}</button>`).join('')}</div>
<div id="stw"><div class="sp"><h3 class="t">${t('sale_h')}</h3>${cdEl()}</div><div class="hs" id="strip"></div></div>
<div class="sp" style="flex-wrap:wrap"><h3 class="t" style="margin:0">${S.f=='all'?E(S.cat=='Barchasi'?t('all'):cn(S.cat)):t(S.f)}: <span id="cnt"></span></h3><div class="opts"><button class="chip ${S.fo?'blue':''}" onclick="S.fo=!S.fo;render()">⚙ ${t('filter')}</button><select class="srt" onchange="S.sort=this.value;grid()">${['def','lo','hi','new','sale'].map(k=>`<option value="${k}" ${S.sort==k?'selected':''}>${t('s_'+k)}</option>`).join('')}</select></div></div>
${S.fo?`<div class="fp"><label>${t('pfrom')}<input type="number" min="0" value="${S.fl.min}" oninput="S.fl.min=this.value;grid()"></label><label>${t('pto')}<input type="number" min="0" value="${S.fl.max}" oninput="S.fl.max=this.value;grid()"></label><label class="ck"><input type="checkbox" ${S.fl.sale?'checked':''} onchange="S.fl.sale=this.checked;grid()">${t('osale')}</label><label class="ck"><input type="checkbox" ${S.fl.stock?'checked':''} onchange="S.fl.stock=this.checked;grid()">${t('ostock')}</label><button class="chip" onclick="resetF()">${t('reset')}</button></div>`:''}
<div class="g" id="grid" style="margin-top:14px"></div><div id="rvw"></div>${trust()}
<div id="s-trk" class="tb"><h3 class="t">${t('tr_t')}</h3><div class="sp"><input id="tq" placeholder="${t('tr_ph')}" onkeydown="event.key=='Enter'&&track()"><button class="chip blue" onclick="track()">${t('tr_btn')}</button></div><div id="tr"></div></div>
<div id="s-faq" class="faq"><h3 class="t">${t('faq_t')}</h3>${[1,2,3,4,5].map(i=>`<div class="fq"><button onclick="this.parentNode.classList.toggle('on')">${t('q'+i)}<i>+</i></button><div><p class="mut">${t('a'+i,{n:i==2?((S.set.warranty['*']||{}).return||14):fmt(S.set.free_ship)})}</p></div></div>`).join('')}</div>`;
function hero(){const b=S.banners;if(!b.length)return'';return `<div id="s-hero" class="hero" onmouseenter="clearInterval(CT)" onmouseleave="heroPlay()" ontouchstart="TX=event.touches[0].clientX" ontouchend="heroGo(event.changedTouches[0].clientX<TX-40?1:event.changedTouches[0].clientX>TX+40?-1:0)"><div class="trk" id="trk">${b.map(x=>{const g=String(x.grad).split(',');return `<div class="sl"><div class="bgk" style="background-image:url(img/${E(x.image)})"></div><div class="ov" style="background:linear-gradient(100deg,${g[0]}f2 0%,${g[0]}b0 38%,${g[1]||g[0]}00 78%)"></div><div class="sc"><div class="tx"><span class="bdg">${E(x.badge||t('sale'))}</span><h2>${E(x.title)}</h2><p>${E(x.subtitle)}</p>${x.category=='__sale'?cdEl():''}<button class="btn cta" onclick="bannerGo(${x.id})">${E(x.cta)} →</button></div></div></div>`}).join('')}</div><button class="arw l" onclick="heroGo(-1)">‹</button><button class="arw r" onclick="heroGo(1)">›</button><div class="dots">${b.map((x,i)=>`<i onclick="heroSet(${i})"></i>`).join('')}</div></div>`}
function heroSet(i){const n=S.banners.length,x=$('#trk');if(!n||!x)return;CI=(i+n)%n;x.style.transform=`translateX(-${CI*100}%)`;document.querySelectorAll('.dots i').forEach((e,k)=>e.classList.toggle('on',k==CI));document.querySelectorAll('.sl').forEach((e,k)=>e.classList.toggle('act',k==CI))}
const heroGo=n=>n&&heroSet(CI+n);
function heroPlay(){clearInterval(CT);CT=setInterval(()=>{if(S.view=='shop'&&$('#md').classList.contains('hide'))heroSet(CI+1)},6000)}
function bannerGo(id){const b=S.banners.find(x=>x.id==id);S.q='';if(b.category=='__sale'){S.cat='Barchasi';S.f='sale'}else{S.cat=b.category;S.f='all'}render();$('.chips').scrollIntoView({behavior:'smooth'})}
function list(){const q=S.q.toLowerCase(),f=S.fl,mn=+f.min||0,mx=+f.max||Infinity;let a=S.products.filter(p=>(S.cat=='Barchasi'||p.category==S.cat)&&p.name.toLowerCase().includes(q)&&(S.f=='all'||(S.f=='sale'?sale(p)>0:p.badge==S.f))&&p.price>=mn&&p.price<=mx&&(!f.sale||sale(p)>0)&&(!f.stock||p.stock>0));
if(S.sort=='lo')a.sort((x,y)=>x.price-y.price);if(S.sort=='hi')a.sort((x,y)=>y.price-x.price);if(S.sort=='new')a.sort((x,y)=>y.id-x.id);if(S.sort=='sale')a.sort((x,y)=>sale(y)-sale(x));return a}
const tags=p=>{const d=sale(p);return(d?`<span class="tg r">-${d}%</span>`:'')+(p.badge=='new'?`<span class="tg c">${t('new')}</span>`:'')+(p.badge=='hit'?`<span class="tg a">${t('hit')}</span>`:'')};
const card=(p,i,cls='')=>{const d=sale(p),lo=p.stock>0&&p.stock<5,n=p.images.length;return `<div class="pc ${cls}" style="animation-delay:${wd(i)}s" onclick="openP(${p.id})"><div class="im" data-i="0" style="background-image:url(img/${p.images[0]||'none.jpg'})">${n>1?`<div class="im2" style="background-image:url(img/${p.images[1]})"></div>`:''}<div class="bs">${tags(p)}</div><div class="ia"><button class="chip sm ${S.wish.includes(p.id)?'on':''}" onclick="event.stopPropagation();wish(${p.id})">♡</button><button class="chip sm ${S.cmp.includes(p.id)?'blue':''}" title="${t('cmp')}" onclick="event.stopPropagation();cmpT(${p.id})">⇄</button></div>${n>1?`<button class="ca l" onclick="ci(event,this,${p.id},-1)">‹</button><button class="ca r" onclick="ci(event,this,${p.id},1)">›</button><div class="cdots">${p.images.map((_,k)=>`<i class="${k?'':'on'}"></i>`).join('')}</div>`:''}</div><p class="nm">${E(p.name)}</p>${stars(p)}<small class="${p.stock<1?'out':lo?'low':'mut'}">${p.stock<1?t('out'):lo?t('low',{n:p.stock}):t('avail',{n:p.stock})}</small>${insB(p.price)}<div class="sp"><span><span class="pr">${fmt(p.price)}</span> ${d?`<s class="old">${fmt(p.old_price)}</s>`:''}</span><button class="chip blue sm" onclick="event.stopPropagation();quick(${p.id})">+</button></div></div>`};
function ci(e,b,id,n){e.stopPropagation();const im=b.closest('.im'),p=P(id);im.classList.add('u');const _=0,l=p.images.length,i=(+im.dataset.i+n+l)%l;im.dataset.i=i;im.style.backgroundImage=`url(img/${p.images[i]})`;im.querySelectorAll('.cdots i').forEach((x,k)=>x.classList.toggle('on',k==i))}
function grid(){if(!$('#grid'))return;const a=list(),sl=S.products.filter(p=>sale(p)>0);$('#cnt').textContent=a.length+' '+t('items');$('#grid').innerHTML=a.map((p,i)=>card(p,i)).join('')||nfHtml();
$('#stw').classList.toggle('hide',!(sl.length&&S.cat=='Barchasi'&&S.f=='all'&&!S.q&&!S.fl.min&&!S.fl.max&&!S.fl.sale&&!S.fl.stock));$('#strip').innerHTML=sl.map((p,i)=>card(p,i)).join('');mmUpdate()}
function rvRow(){const w=$('#rvw');if(!w)return;const a=S.rv.map(P).filter(Boolean);w.innerHTML=a.length?`<div class="sp"><h3 class="t">${t('recent')}</h3><button class="chip sm" onclick="S.rv=[];save();rvRow()">${t('clear')}</button></div><div class="hs">${a.map((p,i)=>card(p,i)).join('')}</div>`:''}
function wish(id){S.wish=S.wish.includes(id)?S.wish.filter(x=>x!=id):[...S.wish,id];save();grid();rvRow();if(S.view=='wish')render()}
function cmpT(id){if(S.cmp.includes(id))S.cmp=S.cmp.filter(x=>x!=id);else if(S.cmp.length>=3)return toast(t('cmp_max'),1);else S.cmp.push(id);grid();rvRow();fab()}
function cmpOpen(){const a=S.cmp.map(P).filter(Boolean);if(!a.length)return;const row=(l,f)=>`<tr><th>${l}</th>${a.map(p=>`<td>${f(p)}</td>`).join('')}</tr>`;
modal(`<div class="sp"><h2>${t('cmp_t')}</h2><button class="chip" onclick="closeM()">✕</button></div><div class="cmp"><table>${row('',p=>`<div class="ph2" style="background-image:url(img/${p.images[0]||'none.jpg'})"></div><b>${E(p.name)}</b>`)}${row(t('price'),p=>`<b class="pr">${fmt(p.price)} ${t('som')}</b>${sale(p)?`<br><s class="old">${fmt(p.old_price)}</s> <span class="tg r">-${sale(p)}%</span>`:''}`)}${row(t('rating'),p=>p.rcount?`★ ${p.rating.toFixed(1)} (${p.rcount})`:'—')}${row(t('cat'),p=>E(cn(p.category)))}${row(t('colors'),p=>E(p.colors.join(', ')))}${row(t('sizes'),p=>E(p.sizes.join(', ')))}${row(t('availability'),p=>p.stock<1?`<span class="out">${t('out')}</span>`:`<span style="color:var(--gr)">${t('avail',{n:p.stock})}</span>`)}${row('',p=>`<button class="chip blue sm" onclick="closeM();openP(${p.id})">${t('open')}</button> <button class="chip sm" onclick="cmpT(${p.id});cmpOpen()">${t('remove')}</button>`)}</table></div>${a.length<2?`<p class="mut">${t('cmp_hint')}</p>`:''}`,1)}
/* ---------- mahsulot oynasi ---------- */
function addCart(p,size,color,n=1){const av=vs(p,size);if(av<1)return toast(t('out'),1);const c=S.cart.find(x=>x.id==p.id&&x.size==size&&x.color==color),have=c?c.qty:0;if(have+n>av)return toast(t('stock_lim',{n:av}),1);if(c)c.qty+=n;else S.cart.push({id:p.id,size,color,qty:n});save();toast(t('added'));bar();flyTo();const bb=$('#bar');if(bb){bb.classList.remove('bump');void bb.offsetWidth;bb.classList.add('bump')}}
const quick=id=>{const p=P(id);if(p.sizes.length>1){toast(t('pick'));return openP(id)}addCart(p,p.sizes[0]||'',p.colors[0]||'')};
function openP(id){const p=P(id);if(!p)return;history.replaceState(null,'','#p'+id);D={p,i:0,size:p.sizes.length==1?p.sizes[0]:'',color:p.colors[0]||'',qty:1,chart:false,rate:0};
S.rv=[id,...S.rv.filter(x=>x!=id)].slice(0,8);save();rvRow();dm(1);
api('view',{id}).then(v=>{const e=$('#lv');if(e&&D&&D.p.id==id)e.innerHTML=`<span class="live"></span>${t('viewing',{n:v.viewing})}${v.today?' · '+t('today',{n:v.today}):''}`}).catch(()=>{});loadRV()}
const gi=n=>{D.i=(D.i+n+D.p.images.length)%D.p.images.length;dm()};
const dq=n=>{D.qty=Math.max(1,Math.min(vs(D.p,D.size)||1,D.qty+n));dm()};
const pickSize=k=>{D.size=D.p.sizes[k];D.qty=Math.min(D.qty,Math.max(1,vs(D.p,D.size)));dm()};
const pickColor=k=>{D.color=D.p.colors[k];const x=D.p.cimg[D.color];if(x!==undefined&&D.p.images[x])D.i=x;dm()};
const needSize=()=>{if(D.size)return false;const g=$('.szg');g.classList.remove('shake');void g.offsetWidth;g.classList.add('shake');toast(t('pick'),1);return true};
const dAdd=()=>{if(needSize())return;addCart(D.p,D.size,D.color,D.qty);closeM()};
function dres(){const{p,size,qty}=D,a=vp(p,size)*qty,r=dlv(a),w=S.set.warranty,wr=Object.assign({},w['*']||{},w[p.category]||{});
return `<div class="dcr"><span>${t('dprice')}: <b>${r.free?`<span style="color:var(--gr)">${t('free')}</span>`:fmt(r.price)+' '+t('som')}</b></span><span>${t('eta')}: <b>${eta(r)}</b></span></div><div class="dcr mut">${wr.return?`<span>${t('ret',{n:wr.return})}</span>`:''}${wr.warranty?`<span>${t('war',{n:wr.warranty})}</span>`:''}</div>`}
const dset=(k,v)=>{S[k]=v;localStorage[k]=v;$('#dres').innerHTML=dres()};
function dm(first){const{p,i,size,color,qty,chart}=D,n=p.images.length,av=vs(p,size),lo=av>0&&av<5,pr=vp(p,size),o=vo(p,size),sim=S.products.filter(x=>x.category==p.category&&x.id!=p.id).slice(0,5),tops=['S','M','L','XL'].some(x=>p.sizes.includes(x));const lv=$('#lv')?.innerHTML||'',rv=$('#rv')?.innerHTML||'';
modal(`<button class="chip xx" onclick="closeM()">✕</button><div class="pd"><div><div class="big" style="background-image:url(img/${p.images[i]||'none.jpg'})">${n>1?`<button class="arw l" onclick="gi(-1)">‹</button><button class="arw r" onclick="gi(1)">›</button><span class="cn">${i+1} / ${n}</span>`:''}<div class="bs">${tags(p)}</div></div><div class="th">${p.images.map((m,k)=>`<i class="${k==i?'on':''}" style="background-image:url(img/${m})" onclick="D.i=${k};dm()"></i>`).join('')}</div></div>
<div class="pi"><small class="mut">${E(cn(p.category))} · ${t('art')} #${p.id}</small><h2>${E(p.name)}</h2>${p.rcount?`<div class="rt">${stars(p)}</div>`:''}<div class="pw"><b class="pr l">${fmt(pr)} ${t('som')}</b>${o?`<s class="old">${fmt(o)}</s><span class="tg r">-${sale(p)}%</span>`:''}</div>${insB(pr)}<button class="chip sm" style="align-self:flex-start" onclick="shareP(${p.id})">🔗 ${t('share')}</button>${av<1?`<button class="chip blue" style="align-self:flex-start" onclick="notifyOpen(${p.id})">🔔 ${t('notify_me')}</button>`:''}<small style="color:${av<1?'var(--ro)':lo?'var(--am)':'var(--gr)'}">${av<1?t('out'):lo?t('low',{n:av}):t('instock')+': '+av}</small><div class="lvb" id="lv">${lv}</div>
<div class="blk"><div class="sp"><b>${t('color')}</b><span class="mut">${E(color)}</span></div><div class="sw">${p.colors.map((c,k)=>`<button class="swb ${c==color?'on':''}" title="${E(c)}" style="background:${CM[c]||'#64748b'}" onclick="pickColor(${k})"></button>`).join('')}</div></div>
<div class="blk"><div class="sp"><b>${t('size')}</b>${tops?`<a class="lnk" onclick="D.chart=!D.chart;dm()">${t('chart')}</a>`:''}</div><div class="szg">${p.sizes.map((c,k)=>{const sv=vs(p,c),ax=ad(p,c);return `<button class="szb ${c==size?'on':''} ${sv<1?'nx':''}" ${sv<1?'disabled':''} onclick="pickSize(${k})">${E(c)}${ax?`<small>+${fmt(ax)}</small>`:''}</button>`}).join('')}</div>${chart&&tops?`<table class="ct"><tr><th>${t('size')}</th><th>${t('chest')}</th></tr><tr><td>S</td><td>88–94</td></tr><tr><td>M</td><td>94–100</td></tr><tr><td>L</td><td>100–106</td></tr><tr><td>XL</td><td>106–112</td></tr></table><small class="mut">${t('approx')}</small>`:''}</div>
<div class="sp qr"><div class="qty"><button onclick="dq(-1)">−</button><b>${qty}</b><button onclick="dq(1)">+</button></div><button class="btn" onclick="dAdd()">${t('add')} · ${fmt(pr*qty)}</button><button class="chip ${S.wish.includes(p.id)?'on':''}" onclick="wish(${p.id});dm()">♡</button></div>
<div class="sp qr"><button class="btn alt" onclick="qo()">⚡ ${t('qorder')}</button><button class="chip ${S.cmp.includes(p.id)?'blue':''}" onclick="cmpT(${p.id});dm()">⇄ ${t('cmp')}</button></div>
<div class="dc"><b>${t('dlv')}</b><div class="sp"><select onchange="dset('reg',this.value)">${['tashkent','tashkent_obl','other'].map(k=>`<option value="${k}" ${S.reg==k?'selected':''}>${t('r_'+k)}</option>`).join('')}</select><select onchange="dset('mth',this.value)">${['courier','pickup'].map(k=>`<option value="${k}" ${S.mth==k?'selected':''}>${t('m_'+k)}</option>`).join('')}</select></div><div id="dres">${dres()}</div></div>
<div class="acc"><h4>${t('descr')}</h4><p class="mut">${E(p.descr)}</p><table class="inf2"><tr><td>${t('cat')}</td><td>${E(cn(p.category))}</td></tr><tr><td>${t('colors')}</td><td>${E(p.colors.join(', '))}</td></tr><tr><td>${t('sizes')}</td><td>${E(p.sizes.join(', '))}</td></tr></table></div></div></div>
<div id="rv">${rv}</div>${sim.length?`<h3 class="t" style="margin-top:20px">${t('similar')}</h3><div class="hs">${sim.map((x,k)=>card(x,k,'mini')).join('')}</div>`:''}`,1,!first)}
/* ---------- sharhlar ---------- */
async function loadRV(){const id=D.p.id;try{const r=await api('reviews',{id});if(!D||D.p.id!=id)return;D.rv=r;rvDraw()}catch(e){}}
function rvDraw(){const e=$('#rv');if(!e||!D.rv)return;const r=D.rv,avg=r.length?(r.reduce((s,x)=>s+x.rating,0)/r.length).toFixed(1):'';
e.innerHTML=`<h3 class="t" style="margin-top:20px">${t('rev')} ${avg?`<span class="rt"><span>★</span> ${avg}</span> <span class="mut" style="font-size:16px">(${r.length})</span>`:''}</h3><div class="rvl">${r.map(x=>`<div class="rvi"><div class="sp"><b>${E(x.name)}</b><span class="rt"><span>${'★'.repeat(x.rating)}</span><span class="mut">${'★'.repeat(5-x.rating)}</span></span></div><p class="mut">${E(x.text)}</p>${admin()?`<a class="lnk" onclick="rvDel(${x.id})">✕</a>`:''}</div>`).join('')||`<p class="mut">${t('rev_none')}</p>`}</div>
<div class="rvf"><b>${t('rev_w')}</b><div class="stp">${[1,2,3,4,5].map(k=>`<button class="${k<=D.rate?'on':''}" onclick="D.rate=${k};rvDraw()">★</button>`).join('')}</div><textarea id="rvt" rows="2" placeholder="${t('rev_ph')}"></textarea><button class="chip blue" onclick="rvSend()">${t('send')}</button></div>`}
const rvSend=()=>run(async()=>{if(!S.user){return authOpen('login')}if(!D.rate)return toast(t('pick_star'),1);const tx=$('#rvt').value;await api('review_add',{id:D.p.id,rating:D.rate,text:tx});D.rate=0;toast(t('rev_ok'));await load();D.p=P(D.p.id);loadRV()});
const rvDel=id=>run(async()=>{await api('review_delete',{id});await load();D.p=P(D.p.id);loadRV()});
/* ---------- savat ---------- */
const regSel=(id,on)=>`<select ${id?`id="${id}"`:''} onchange="${on}">${['tashkent','tashkent_obl','other'].map(k=>`<option value="${k}" ${S.reg==k?'selected':''}>${t('r_'+k)}</option>`).join('')}</select>`;
const mthSel=(id,on)=>`<select ${id?`id="${id}"`:''} onchange="${on}">${['courier','pickup'].map(k=>`<option value="${k}" ${S.mth==k?'selected':''}>${t('m_'+k)}</option>`).join('')}</select>`;
const cset=(k,v)=>{S[k]=v;localStorage[k]=v;cartOpen(1);bar()};
function cartOpen(na){if(!cnt())return toast(t('cart_empty'),1);const u=S.user||{},a=sub()-disc(),r=dlv(a),left=Math.max(0,S.set.free_ship-a);
modal(`<div class="sp"><h2>${t('cart')}</h2><div class="opts"><button class="chip sm" onclick="clearCart()">🗑 ${t('cl_cart')}</button><button class="chip" onclick="closeM()">✕</button></div></div>${S.cart.map((c,i)=>{const p=P(c.id);return p?`<div class="row"><div class="ph" style="background-image:url(img/${p.images[0]})"></div><div class="fl"><p class="nm">${E(p.name)}</p><small class="mut">${E(c.size)} ${E(c.color)} · ${fmt(vp(p,c.size))}</small></div><button class="chip sm" onclick="qty(${i},-1)">−</button><b>${c.qty}</b><button class="chip sm" onclick="qty(${i},1)">+</button></div>`:''}).join('')}
<div class="sp"><input id="pc" placeholder="${t('promo')}" value="${S.promo?S.promo.code:''}"><button class="chip blue" onclick="promo()">${t('apply')}</button></div>
<div class="sp">${regSel('',"cset('reg',this.value)")}${mthSel('',"cset('mth',this.value)")}</div>
${S.mth=='courier'?`<div class="fsw"><small>${left?t('fs_left',{n:fmt(left)}):t('fs_ok')}</small><div class="fsb big"><i style="width:${Math.min(100,a/S.set.free_ship*100)}%"></i></div></div>`:''}
<p>${S.promo?`${t('disc')}: −${fmt(disc())} ${t('som')} (${S.promo.code})<br>`:''}${t('dprice')}: ${r.free?`<b style="color:var(--gr)">${t('free')}</b>`:fmt(r.price)+' '+t('som')} · ${t('eta')}: ${eta(r)}<br>${t('total')}: <b class="pr">${fmt(a+r.price)} ${t('som')}</b></p>
<input id="on" placeholder="${t('name')}" value="${E(u.name||'')}"><input id="op" placeholder="${t('phone')}" value="${E(u.phone||'')}"><input id="oa" placeholder="${t('addr')}" value="${E(u.address||'')}">
${payBox()}<button class="btn" onclick="order()">${t('order')}</button>${S.user?'':`<small class="mut">${t('need_login')}</small>`}`,0,na)}
const qty=(i,n)=>{const c=S.cart[i],p=P(c.id),av=vs(p,c.size);c.qty+=n;if(c.qty>av){c.qty=av;toast(t('stock_lim',{n:av}),1)}if(c.qty<1)S.cart.splice(i,1);save();bar();cnt()?cartOpen(1):closeM()};
const promo=()=>run(async()=>{S.promo=await api('promo',{code:$('#pc').value});toast(t('promo_ok'));cartOpen(1);bar()});
const order=()=>run(async()=>{if(!S.user){closeM();return authOpen('register')}
const r=await api('order',{items:S.cart,promo:S.promo?S.promo.code:'',name:$('#on').value,phone:$('#op').value,address:$('#oa').value,region:S.reg,method:S.mth,pay:payOk()});S.cart=[];S.promo=null;save();closeM();if(r.pay_url){toast(t('pay_redirect'));setTimeout(()=>{location.href=r.pay_url},700);return}toast(t('ordered'));confetti();await load();go('orders')});
/* ---------- tezkor buyurtma ---------- */
function qo(){if(needSize())return;const{p,size,color,qty}=D,u=S.user||{};
modal(`<div class="sp"><h2>⚡ ${t('qorder')}</h2><button class="chip" onclick="closeM()">✕</button></div><p class="mut">${t('qo_h')}</p><div class="row"><div class="ph" style="background-image:url(img/${p.images[0]})"></div><div class="fl"><p class="nm">${E(p.name)}</p><small class="mut">${E(size)} ${E(color)} × ${qty}</small></div><b>${fmt(vp(p,size)*qty)}</b></div>
<label class="fi"><input id="qn" placeholder=" " value="${E(u.name||'')}"><span>${t('name')}</span></label><label class="fi ph"><b>+998</b><input id="qp" inputmode="numeric" maxlength="12" placeholder=" " oninput="mask(this)"><span>${t('phone')}</span></label>
<div class="sp">${regSel('qr','qsum()')}${mthSel('qm','qsum()')}</div><p id="qs"></p><p class="er" id="qe"></p><button class="btn" id="qb" onclick="qsend()">${t('qorder')}</button>`);qsum()}
function qsum(){S.reg=$('#qr').value;S.mth=$('#qm').value;localStorage.reg=S.reg;localStorage.mth=S.mth;const a=vp(D.p,D.size)*D.qty,r=dlv(a);$('#qs').innerHTML=`${t('dprice')}: ${r.free?`<b style="color:var(--gr)">${t('free')}</b>`:fmt(r.price)+' '+t('som')} · ${t('eta')}: ${eta(r)}<br>${t('total')}: <b class="pr">${fmt(a+r.price)} ${t('som')}</b>`}
async function qsend(){const e=$('#qe'),b=$('#qb'),ph=$('#qp').value.replace(/\D/g,''),bad=x=>{e.textContent=x;e.classList.remove('shake');void e.offsetWidth;e.classList.add('shake')};
if(!$('#qn').value.trim())return bad(t('name_err'));if(ph.length!=9)return bad(t('phone_err'));b.disabled=true;b.textContent=t('wait');
try{const{p,size,color,qty}=D,r=await api('quick_order',{id:p.id,size,color,qty,name:$('#qn').value,phone:'998'+ph,region:S.reg,method:S.mth});await load();confetti();modal(`<div class="ok"><span class="okc">✓</span><h2>${t('ordered')}</h2><p class="mut">${t('qo_ok',{n:r.id})}</p><button class="btn" onclick="closeM()">${t('close')}</button></div>`)}catch(x){bad(x.message);b.disabled=false;b.textContent=t('qorder')}}
/* ---------- auth ---------- */
const fi=(id,l,ty='text')=>`<label class="fi"><input id="${id}" type="${ty}" placeholder=" " autocomplete="off"><span>${l}</span></label>`;
function authOpen(m){const r=m=='register';modal(`<button class="chip xx" onclick="closeM()">✕</button><div class="auth"><div class="ap"><span class="logo">TS</span><h2>${r?t('create'):t('welcome')}</h2><p>${r?t('au_r'):t('au_l')}</p><ul><li>${t('b1')}</li><li>${t('b2')}</li><li>${t('b3')}</li></ul></div>
<div class="af"><div class="tabs"><i style="transform:translateX(${r?100:0}%)"></i><button class="${r?'':'on'}" onclick="authOpen('login')">${t('login')}</button><button class="${r?'on':''}" onclick="authOpen('register')">${t('reg')}</button></div>
<form onsubmit="event.preventDefault();auth('${m}')">${r?fi('an',t('name')):''}<label class="fi ph"><b>+998</b><input id="ap" inputmode="numeric" maxlength="12" placeholder=" " oninput="mask(this)"><span>${t('phone')}</span></label>${r?fi('aa',t('addr_opt')):''}<label class="fi"><input id="aw" type="password" placeholder=" " ${r?'oninput="pw(this.value)"':''}><span>${t('pass')}</span><button type="button" class="eye" onclick="eye()">${t('show')}</button></label>${r?`<div class="str"><i></i><i></i><i></i><i></i></div><small class="mut" id="sl">${t('pw_hint')}</small>`:''}<p class="er" id="ae"></p><button class="btn" id="ab">${r?t('reg_btn'):t('login')}</button></form></div></div>`,1);setTimeout(()=>$(r?'#an':'#ap').focus(),50)}
const mask=e=>{const x=e.value.replace(/\D/g,'').slice(0,9);e.value=[x.slice(0,2),x.slice(2,5),x.slice(5,7),x.slice(7,9)].filter(Boolean).join(' ')};
const eye=()=>{const w=$('#aw'),h=w.type=='password';w.type=h?'text':'password';$('.eye').textContent=h?t('hide'):t('show')};
function pw(v){const sc=(v.length>=6)+(/\d/.test(v)&&/[a-zA-Z]/.test(v))+(v.length>=10)+(/[A-Z]/.test(v)&&/[a-z]/.test(v));const c=['#f43f5e','#f59e0b','#22d3ee','#34d399'][Math.max(0,sc-1)];document.querySelectorAll('.str i').forEach((e,k)=>e.style.background=k<sc?c:'');$('#sl').textContent=v?t('pw'+sc):t('pw_hint')}
async function auth(m){const e=$('#ae'),b=$('#ab'),r=m=='register',ph=$('#ap').value.replace(/\D/g,''),w=$('#aw').value;
const bad=x=>{e.textContent=x;e.classList.remove('shake');void e.offsetWidth;e.classList.add('shake')};
if(r&&!$('#an').value.trim())return bad(t('name_err'));if(ph.length!=9)return bad(t('phone_err'));if(w.length<(r?6:1))return bad(r?t('pw_short'):t('pw_req'));
b.disabled=true;b.textContent=t('wait');
try{const x={phone:'998'+ph,pass:w};if(r){x.name=$('#an').value;x.address=$('#aa').value}S.user=(await api(m,x)).user;await syncRun('merge');closeM();toast(t('hello',{n:S.user.name}));await load();render()}catch(x){bad(x.message);b.disabled=false;b.textContent=r?t('reg_btn'):t('login')}}
const logout=()=>run(async()=>{await api('logout');S.user=null;localStorage.removeItem('synced');S.cart=[];S.wish=[];S.promo=null;save();S.view='shop';await load();render()});
/* ---------- buyurtma holati ---------- */
const track=()=>run(async()=>{const r=await api('track',{q:$('#tq').value});$('#tr').innerHTML=r.length?r.map(o=>{const i=STK.indexOf(o.status);return `<div class="ord" style="margin-top:12px"><div class="sp"><b>#${o.id}</b><span class="badge s-${o.status}">${t('st_'+o.status)}</span></div>${o.status=='cancel'?'':`<div class="steps">${['new','confirmed','shipping','done'].map((k,j)=>`<div class="${j<=i?'on':''}"><i>${j+1}</i><small>${t('st_'+k)}</small></div>`).join('')}</div>`}<small class="mut">${E(o.created_at)}</small>${o.items.map(x=>`<p>${E(x.title)} <span class="mut">${E(x.size)} × ${x.qty}</span></p>`).join('')}<b class="pr">${fmt(o.total)} ${t('som')}</b></div>`}).join(''):`<p class="mut" style="margin-top:12px">${t('tr_none')}</p>`});
/* ---------- buyurtmalar ---------- */
V.orders=()=>`<h3 class="t">${staff()?t('all_orders'):t('my_orders')}</h3><div class="list">${S.orders.map(o=>`<div class="ord"><div class="sp"><b>#${o.id}</b><span class="badge s-${o.status}">${t('st_'+o.status)}</span></div><small class="mut">${E(o.created_at)} · ${E(o.name)} · ${E(o.phone)} · ${E(o.address)}</small>${o.status=='cancel'?'':stepsH(o.status)}${o.items.map(i=>`<p>${E(i.title)} <span class="mut">${E(i.size)} ${E(i.color)} × ${i.qty}</span></p>`).join('')}<div class="sp"><b class="pr">${fmt(o.total)} ${t('som')}</b><small class="mut">${o.discount?t('disc')+' −'+fmt(o.discount)+' · ':''}${t('dprice')}: ${o.delivery?fmt(o.delivery):t('free')}</small></div>${payRow(o)}${staff()&&o.status!='cancel'?`<div class="opts">${STK.map(k=>`<button class="chip sm ${o.status==k?'blue':''}" onclick="ost(${o.id},'${k}')">${t('st_'+k)}</button>`).join('')}</div>`:''}</div>`).join('')||`<p class="mut">${t('no_orders')}</p>`}</div>`;
const ost=(id,status)=>run(async()=>{await api('order_status',{id,status});S.orders=await api('orders');await load();render()});
/* ---------- ombor ---------- */
V.stock=()=>{const o=S.orders,low=S.products.filter(p=>p.stock<5).length,rev=o.filter(x=>x.status!='cancel').reduce((s,x)=>s+x.total,0),tot=S.products.reduce((s,p)=>s+p.stock,0);
return `<div class="stats"><div class="st">Jami zaxira<b>${tot}</b></div><div class="st">Buyurtmalar<b>${o.length}</b></div><div class="st">Daromad<b>${fmt(rev)}</b></div><div class="st">Kam qolgan<b style="color:${low?'var(--ro)':'var(--gr)'}">${low}</b></div></div>
<div class="sp" style="margin-bottom:14px"><h3 class="t">Ombordagi qoldiqlar</h3><div class="opts">${admin()?'<button class="chip blue" onclick="pOpen()">+ Yangi mahsulot</button>':''}<button class="chip" onclick="exp()">Eksport</button><button class="chip" onclick="notifyList()">🔔</button>${admin()?'<button class="chip" onclick="csvExp()">CSV ↓</button><button class="chip" onclick="csvPick()">CSV ↑</button><input id="csvf" type="file" accept=".csv,text/csv" hidden onchange="csvImp(this)">':''}</div></div><div class="list">${S.products.map(p=>`<div class="row"><div class="ph" style="background-image:url(img/${p.images[0]||'none.jpg'})"></div><div class="fl"><p class="nm">${E(p.name)}</p><small class="mut">${E(p.category)} · ${fmt(p.price)}</small></div>${p.variants?'':`<button class="chip sm" onclick="stk(${p.id},-1)">−</button>`}<b style="color:${p.stock<5?'var(--ro)':'inherit'}">${p.stock}</b>${p.variants?'':`<button class="chip sm" onclick="stk(${p.id},1)">+</button>`}${admin()?`<button class="chip sm" onclick="pOpen(${p.id})">✎</button><button class="chip sm" onclick="del(${p.id})">✕</button>`:''}</div>`).join('')}</div>`};
const stk=(id,d)=>run(async()=>{await api('stock',{id,d});await load();render()});
const exp=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(S.products,null,2)],{type:'application/json'}));a.download='trend-store.json';a.click()};
function pOpen(id){const p=id?P(id):{name:'',category:'',price:'',old_price:'',cost:'',stock:'',sizes:[],colors:[],descr:'',badge:''},f=(k,l,v)=>`<input id="f${k}" placeholder="${l}" value="${E(v)}">`;
modal(`<div class="sp"><h2>${id?'Tahrirlash':'Yangi mahsulot'}</h2><button class="chip" onclick="closeM()">✕</button></div>${f('n','Nomi',p.name)}${f('c','Kategoriya',p.category)}${f('p','Narx',p.price)}${f('o','Eski narx (aksiya uchun, ixtiyoriy)',p.old_price||'')}${f('k','Tannarx',p.cost)}${f('s','Zaxira',p.stock)}${f('z',"O'lchamlar (vergul bilan)",p.sizes.join(', '))}${f('r','Ranglar (Qora:0, Kulrang:3 — ikkinchi son rasm raqami)',p.colors_raw||'')}<select id="fb"><option value="">Belgi: yo'q</option><option value="new" ${p.badge=='new'?'selected':''}>Yangi</option><option value="hit" ${p.badge=='hit'?'selected':''}>Ommabop</option></select><input id="fi" type="file" accept="image/*"><textarea id="fv" rows="3" placeholder="Variantlar: har qatorda nom|zaxira|+narx (masalan S|5|0)">${E(vtxt(p))}</textarea><textarea id="fd" rows="3" placeholder="Tavsif">${E(p.descr)}</textarea><button class="btn" onclick="pSave(${id||0})">Saqlash</button>`)}
const pSave=id=>run(async()=>{const g=k=>$('#f'+k).value,f=new FormData();f.append('id',id);[['name','n'],['category','c'],['price','p'],['cost','k'],['stock','s'],['sizes','z'],['colors','r'],['descr','d'],['old_price','o'],['badge','b'],['variants','v']].forEach(([a,b])=>f.append(a,g(b)));if($('#fi').files[0])f.append('image',$('#fi').files[0]);
await api('product_save',null,f);closeM();toast('Saqlandi');await load();render()});
const del=id=>modal(`<h2>Ushbu mahsulotni ombordan o'chirmoqchimisiz?</h2><div class="opts"><button class="chip" onclick="closeM()">Bekor</button><button class="chip blue" onclick="delOk(${id})">Ha</button></div>`);
