const thMode=()=>['light','dark'].includes(localStorage.theme)?localStorage.theme:'auto';
function thEff(){const m=thMode();if(m!='auto')return m;if(MQ.matches)return'dark';if(MQL.matches)return'light';const h=new Date().getHours();return h>=19||h<7?'dark':'light'}
function thApply(){const e=thEff();document.documentElement.dataset.theme=e;const m=document.querySelector('meta[name=theme-color]');if(m)m.content=e=='dark'?'#090d16':'#f3f5fa'}
const thIco=()=>({auto:'◐',light:'☀',dark:'☾'})[thMode()];
const thBtn=()=>`<button class="chip" id="thb" onclick="themeCycle()" title="${t('th_set',{m:t('th_'+thMode())})}">${thIco()}</button>`;
function themeCycle(){const n={auto:'light',light:'dark',dark:'auto'}[thMode()];if(n=='auto')localStorage.removeItem('theme');else localStorage.theme=n;thApply();const b=$('#thb');if(b){b.textContent=thIco();b.title=t('th_set',{m:t('th_'+n)})}toast(t('th_set',{m:t('th_'+n)}))}
(MQ.addEventListener?MQ.addEventListener.bind(MQ,'change'):MQ.addListener.bind(MQ))(()=>{if(thMode()=='auto')thApply()});
