/* ---------- topilmadi yordamchisi ---------- */
function lev(a,b){const m=a.length,n=b.length;if(!m)return n;if(!n)return m;let p=Array.from({length:n+1},(_,j)=>j);for(let i=1;i<=m;i++){const c=[i];for(let j=1;j<=n;j++)c[j]=Math.min(p[j]+1,c[j-1]+1,p[j-1]+(a[i-1]==b[j-1]?0:1));p=c}return p[n]}
let NFC=[],NFW=[];
function nfHtml(){const q=S.q.trim().toLowerCase();let words=[],cs=[],ps=[],found=false;
if(q){const qw=q.split(/\s+/).filter(w=>w.length>1),ok=(a,b)=>{const th=Math.max(1,Math.floor(Math.min(a.length,b.length)/3));return lev(a,b)<=th||(a.length>=3&&b.startsWith(a))};
const wmap={};S.products.forEach(p=>p.name.toLowerCase().split(/[^\p{L}\p{N}']+/u).filter(w=>w.length>2).forEach(w=>{wmap[w]=wmap[w]||[];wmap[w].push(p)}));
const sc=new Map();for(const w in wmap)for(const x of qw)if(ok(x,w)){const d=lev(x,w);words.push([w,d]);wmap[w].forEach(p=>sc.set(p,Math.min(sc.get(p)??9,d)))}
words=[...new Map(words.sort((a,b)=>a[1]-b[1]).map(x=>[x[0],x])).values()].slice(0,3).map(x=>x[0]);
cats().forEach(c=>{const names=[c.toLowerCase(),cn(c).toLowerCase()];if(qw.some(x=>names.some(n=>ok(x,n))))cs.push(c)});
ps=[...sc.entries()].sort((a,b)=>a[1]-b[1]).map(x=>x[0]).slice(0,4);found=!!(words.length||cs.length||ps.length)}
if(!found){const cc={};S.products.forEach(p=>cc[p.category]=(cc[p.category]||0)+1);cs=Object.keys(cc).sort((a,b)=>cc[b]-cc[a]).slice(0,6);ps=S.products.filter(p=>p.badge=='hit'&&p.stock>0);if(ps.length<4)ps=ps.concat(S.products.filter(p=>!ps.includes(p)&&p.stock>0));ps=ps.slice(0,4)}
NFC=cs;NFW=words;
return `<div class="nf"><b style="font-size:18px">🔍 ${q?t('nf_h',{q:E(S.q.trim())}):t('nf_h2')}</b><p class="mut">${found?t('nf_try'):t('nf_pop')}</p>${words.length?`<div class="chips">${words.map((w,i)=>`<button class="chip blue" onclick="nfQ(${i})">${E(w)}</button>`).join('')}</div>`:''}${cs.length?`<div class="chips">${cs.map((c,i)=>`<button class="chip" onclick="nfCat(${i})">${E(cn(c))}</button>`).join('')}</div>`:''}${ps.length?`<div class="hs" style="max-width:100%">${ps.map((p,i)=>card(p,i,'mini')).join('')}</div>`:''}<button class="chip" onclick="resetF()">${t('nf_reset')}</button></div>`}
function nfQ(i){S.q=NFW[i];const e=$('#sr');if(e){e.value=S.q;e.classList.remove('hide')}shAdd(S.q);grid()}
function nfCat(i){S.fl={min:'',max:'',sale:false,stock:false};S.q='';S.cat=NFC[i];S.f='all';render();$('#s-cat').scrollIntoView({behavior:'smooth'})}
