let SNT;
function snack(m,a,fn,ms){let e=$('#sn');if(!e){e=document.createElement('div');e.id='sn';document.body.appendChild(e)}e.innerHTML=`<span>${E(m)}</span><button>${E(a)}</button>`;e.querySelector('button').onclick=()=>{e.classList.remove('on');fn()};e.classList.add('on');clearTimeout(SNT);SNT=setTimeout(()=>e.classList.remove('on'),ms)}
