const WRD=/[^\p{L}\p{N}']+/u;
function acMatch(q){q=q.toLowerCase();const sc=p=>{const n=p.name.toLowerCase(),ws=n.split(WRD).filter(Boolean),c=((cn(p.category)||'')+' '+p.category).toLowerCase();
if(n.startsWith(q))return 0;if(ws.some(w=>w.startsWith(q)))return 1;if(n.includes(q))return 2;if(c.includes(q))return 3;
if(q.length>=3&&!/\s/.test(q)){const d=Math.min(9,...ws.filter(w=>w.length>2).map(w=>lev(q,w)));if(d<=Math.max(1,Math.floor(q.length/3)))return 4+d}return 99};
return S.products.map(p=>[sc(p),p]).filter(x=>x[0]<99).sort((a,b)=>a[0]-b[0]||(b[1].stock>0)-(a[1].stock>0)).map(x=>x[1])}
function acSugg(q){q=q.toLowerCase();let best='',bd=9;S.products.forEach(p=>p.name.toLowerCase().split(WRD).filter(w=>w.length>2).forEach(w=>{const d=lev(q,w);if(d<bd&&d<=Math.max(2,Math.floor(w.length/3))){bd=d;best=w}}));return best}
const acMark=(n,q)=>{const i=n.toLowerCase().indexOf(q.toLowerCase());return i<0?E(n):E(n.slice(0,i))+'<mark>'+E(n.slice(i,i+q.length))+'</mark>'+E(n.slice(i+q.length))};
function acOpen(id){shAdd(S.q);const b=$('#sh');b&&b.classList.add('hide');const e=$('#sr');e&&e.blur();openP(id)}
function acAll(){shAdd(S.q);const b=$('#sh');b&&b.classList.add('hide');const e=$('#sr');e&&e.blur();const c=$('#s-cat');c&&c.scrollIntoView({behavior:'smooth'})}
function acPick(){if(!ACW)return;S.q=ACW;const e=$('#sr');if(e)e.value=ACW;grid();shShow()}
function acKey(e){const b=$('#sh'),rows=b?[...b.querySelectorAll('.ac')]:[],n=rows.length;
if(e.key=='ArrowDown'||e.key=='ArrowUp'){if(!n)return;e.preventDefault();ACI=e.key=='ArrowDown'?(ACI+1)%n:(ACI<=0?n-1:ACI-1);rows.forEach((r,k)=>r.classList.toggle('on',k==ACI));rows[ACI].scrollIntoView({block:'nearest'})}
else if(e.key=='Enter'){if(ACI>=0&&rows[ACI]){e.preventDefault();acOpen(+rows[ACI].dataset.id)}else{shAdd(e.target.value);shHide()}}
else if(e.key=='Escape'){b&&b.classList.add('hide');e.target.blur()}}
function openSearch(){if(S.view!='shop'){go('shop');return setTimeout(openSearch,350)}const e=$('#sr');if(!e)return;e.classList.remove('hide');e.focus();e.select();shShow()}
document.addEventListener('keydown',e=>{const tg=e.target&&e.target.tagName,typing=/INPUT|TEXTAREA|SELECT/.test(tg);
if(e.key=='Escape'&&!typing){const m=$('#md');if(m&&!m.classList.contains('hide'))closeM()}
if(!typing&&(e.key=='/'||(e.key=='k'&&(e.ctrlKey||e.metaKey)))){e.preventDefault();openSearch()}
if(e.key=='k'&&(e.ctrlKey||e.metaKey)&&typing){e.preventDefault();openSearch()}});
let REC=null;
