const r=new SR();REC=r;r.lang={uz:'uz-UZ',ru:'ru-RU',en:'en-US'}[lang]||'uz-UZ';r.interimResults=false;r.maxAlternatives=1;
r.onstart=()=>{b&&b.classList.add('rec');toast(t('voice_on'))};
