function flyTo(){const ev=window.event,el=ev&&ev.target&&ev.target.closest?ev.target.closest('.pc,.sheet'):null,im=el&&el.querySelector('.im,.big'),bar=$('#bar .fb')||$('#bar'),dst=bar&&bar.getBoundingClientRect();if(!im||!dst||!dst.width||!Element.prototype.animate)return;
const r=im.getBoundingClientRect(),f=document.createElement('div'),bg=getComputedStyle(im).backgroundImage;f.style.cssText=`position:fixed;z-index:250;left:${r.left+r.width/2-30}px;top:${r.top+r.height/2-30}px;width:60px;height:60px;border-radius:18px;background:${bg} center/cover;box-shadow:0 8px 24px #0006;pointer-events:none`;document.body.appendChild(f);
const dx=dst.left+dst.width/2-(r.left+r.width/2),dy=dst.top+dst.height/2-(r.top+r.height/2);
f.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx*.5}px,${dy*.5-70}px) scale(.8)`,opacity:1,offset:.5},{transform:`translate(${dx}px,${dy}px) scale(.2)`,opacity:.2}],{duration:750,easing:'cubic-bezier(.5,0,.7,.4)'}).onfinish=()=>f.remove()}
