function confetti(){if(!Element.prototype.animate||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const cs=['#2563eb','#22d3ee','#f43f5e','#fbbf24','#a855f7','#10b981'],w=document.createElement('div');w.style.cssText='position:fixed;inset:0;z-index:260;pointer-events:none;overflow:hidden';
for(let i=0;i<70;i++){const p=document.createElement('i'),x=Math.random()*100,sz=6+Math.random()*7;p.style.cssText=`position:absolute;top:-20px;left:${x}%;width:${sz}px;height:${sz*1.6}px;background:${cs[i%cs.length]};border-radius:2px`;w.appendChild(p);
p.animate([{transform:'translate(0,0) rotate(0)',opacity:1},{transform:`translate(${(Math.random()-.5)*240}px,${innerHeight+40}px) rotate(${Math.random()*900}deg)`,opacity:.9}],{duration:1600+Math.random()*1400,delay:Math.random()*350,easing:'cubic-bezier(.2,.6,.4,1)',fill:'forwards'})}
document.body.appendChild(w);setTimeout(()=>w.remove(),3600)}
