const payGo=(id,m)=>run(async()=>{const r=await api('pay_link',{id,pay:m});toast(t('pay_redirect'));setTimeout(()=>{location.href=r.pay_url},500)});
function payNow(id){const l=payList().filter(k=>k!='cash');if(l.length==1)return payGo(id,l[0]);modal(`<div class="sp"><h2>${t('pay_pick')}</h2><button class="chip" onclick="closeM()">✕</button></div><div class="opts" style="margin-top:14px">${l.map(k=>`<button class="btn" onclick="payGo(${id},'${k}')">💳 ${payLbl(k)}</button>`).join('')}</div>`)}
