<div class="pcard"><h4>To'lov usullari</h4>${s.pay.map(x=>row(payLbl(x.m),x.r,x.r/pm,x.n+' ta · '+fmt(x.r))).join('')||'<p class="mut">Hali ma\'lumot yo\'q</p>'}</div>
