/* qaytganda xabar bering */
function notifyOpen(id){const u=S.user||{},p=String(u.phone||''),pf=[p.slice(0,2),p.slice(2,5),p.slice(5,7),p.slice(7,9)].filter(Boolean).join(' ');
modal(`<div class="sp"><h2>🔔 ${t('notify_me')}</h2><button class="chip" onclick="closeM()">✕</button></div><p class="mut">${t('notify_h')}</p><label class="fi ph"><b>+998</b><input id="nmp" inputmode="numeric" maxlength="12" placeholder=" " value="${pf}" oninput="mask(this)"><span>${t('phone')}</span></label><p class="er" id="nme"></p><button class="btn" onclick="notifySend(${id})">${t('save')}</button>`)}
const notifySend=id=>run(async()=>{const ph=$('#nmp').value.replace(/\D/g,'');if(ph.length!=9)return fshake($('#nme'),t('phone_err'));await api('notify_add',{id,phone:'998'+ph,size:(D&&D.size)||''});closeM();toast(t('notify_ok'))});
const notifyList=()=>run(async()=>{const a=await api('notify_list'),g={};a.forEach(x=>(g[x.product_id]=g[x.product_id]||{n:x.name,id:x.product_id,p:[]}).p.push(x));
modal(`<div class="sp"><h2>🔔 Kutayotgan mijozlar</h2><button class="chip" onclick="closeM()">✕</button></div>${Object.values(g).map(x=>`<div class="ord"><div class="sp"><b>${E(x.n)}</b><button class="chip sm" onclick="notifyDone(${x.id})">✔ Xabar berildi</button></div>${x.p.map(y=>`<a class="lnk" href="tel:+998${E(y.phone)}">+998 ${E(y.phone)}</a>${y.size?' ('+E(y.size)+')':''}`).join('<br>')}</div>`).join('')||'<p class="mut">Hozircha hech kim kutmayapti</p>'}`)});
const notifyDone=id=>run(async()=>{await api('notify_done',{id});notifyList()});
/* CSV: mahsulotlarni Excel orqali yuklab olish / yuklash */
const CSVK=['id','name','category','price','old_price','cost','stock','sizes','colors','badge','descr'];
const csvQ=v=>{v=String(v??'');return /[;"\n\r]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v};
function csvExp(){const rows=[CSVK.join(';'),...S.products.map(p=>[p.id,p.name,p.category,p.price,p.old_price||'',p.cost??'',p.stock,p.sizes.join(','),p.colors_raw||'',p.badge||'',p.descr||''].map(csvQ).join(';'))];
const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+rows.join('\r\n')],{type:'text/csv;charset=utf-8'}));a.download='trend-store-mahsulotlar.csv';a.click()}
const csvPick=()=>{const f=$('#csvf');f&&f.click()};
function csvParse(x){x=x.replace(/^\uFEFF/,'');const f=x.split(/\r?\n/)[0]||'',dl=f.split(';').length>f.split(',').length?';':',',rows=[];let r=[],c='',q=false;
for(let i=0;i<x.length;i++){const ch=x[i];if(q){if(ch=='"'){if(x[i+1]=='"'){c+='"';i++}else q=false}else c+=ch}else if(ch=='"')q=true;else if(ch==dl){r.push(c);c=''}else if(ch=='\n'||ch=='\r'){if(ch=='\r'&&x[i+1]=='\n')i++;r.push(c);c='';if(r.some(v=>v!==''))rows.push(r);r=[]}else c+=ch}
r.push(c);if(r.some(v=>v!==''))rows.push(r);return rows}
const CSVA={id:['id'],name:['name','nomi','nom'],category:['category','kategoriya'],price:['price','narx'],old_price:['old_price','eski narx','eski_narx'],cost:['cost','tannarx'],stock:['stock','zaxira'],sizes:['sizes',"o'lchamlar",'olchamlar'],colors:['colors','ranglar'],badge:['badge','belgi'],descr:['descr','tavsif','description']};
function csvImp(inp){const f=inp.files[0];if(!f)return;const rd=new FileReader();rd.onload=()=>run(async()=>{const t0=csvParse(String(rd.result));if(t0.length<2)throw new Error("CSV bo'sh yoki ustun nomlari yo'q");
const h=t0[0].map(v=>v.trim().toLowerCase()),col={};for(const k in CSVA){const i=h.findIndex(v=>CSVA[k].includes(v));if(i>=0)col[k]=i}
if(col.name==null||col.price==null)throw new Error("CSV da 'name' (nomi) va 'price' (narx) ustunlari bo'lishi kerak");
const rows=t0.slice(1).map(r=>{const o={};for(const k in col)o[k]=(r[col[k]]||'').trim();return o});
const res=await api('product_import',{rows});inp.value='';await load();render();toast(`Qo'shildi: ${res.added} · yangilandi: ${res.updated} · o'tkazildi: ${res.skipped}`)});rd.readAsText(f,'utf-8')}
/* PWA */
if('serviceWorker' in navigator&&(location.protocol=='https:'||location.hostname=='localhost'||location.hostname=='127.0.0.1'))addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));
/* ---------- start ---------- */
async function load(){[S.products,S.banners,S.set]=await Promise.all([api('products'),api('banners'),api('settings')]);S.off=S.set.now-Date.now()}
async function boot(){try{S.user=(await api('me')).user;if(S.user)await syncRun(localStorage.synced==S.user.id?'get':'merge');await load();render();if(location.hash=='#orders'&&S.user){history.replaceState(null,'',location.pathname);go('orders')}const hm=/^#p(\d+)$/.exec(location.hash);if(hm&&P(+hm[1]))setTimeout(()=>openP(+hm[1]),900)}catch(e){if(!S.products.length)offScreen();else toast(e.message,1)}finally{preDone()}}
if(!navigator.onLine)offShow();boot();
